using System;
using System.Collections.Immutable;
using System.Linq;
using System.Text.RegularExpressions;
using System.Threading.Tasks;
using ConsoleTables;
using Extensions.Pack;
using AspNetCore.MinimalApi.Sdk.CodeRules.Api.Controllers;
using Solution.Parser.CSharp;

namespace AspNetCore.MinimalApi.Sdk.CodeRules
{
    [TestCategory("Coding-Rules")]
    [TestCategory("API - Controllers")]
    [TestClass]
    public class RJIT_CR_API_C_00025 : ControllerTestBase
    {
        [TestMethod]
        public void If_Return_Type_Is_Just_A_Task_Then_You_Have_To_Return_204_No_Content()
        {
            var wrongStatusCodes = (from controller in Controllers
                                       from method in controller.Methods
                                       where (method.ReturnParameter.EqualsTo(nameof(Task)) ||
                                              method.ReturnParameter.EqualsTo("ActionResult")) &&
                                             method.Attributes.Any(attribute => attribute.Name.StartWith("ProducesResponseType") && attribute.Arguments.Any(argument => argument.Contains("200")))
                                       select new
                                       {
                                           Error = $@"
You do not return an response object, but you use status code 200. You have to use status code 204 for no content
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Controller: {controller.FullQualifiedName}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Return: {method.ReturnParameter}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Method: 

{method.MethodValue.FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
Sample: 

{method.MethodValue.Replace("Status200OK", "Status204NoContent").FormatSyntaxTree()}
------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------------
"
                                       }).ToImmutableList();

            Assert.IsTrue(wrongStatusCodes.IsEmpty(),
                @$"
Documentation: {DocumentationDomain}#RJIT_CR_API_C_00025

Invalid response type detected. Anytime if you return no data. Please use 204 NoContent.: {Environment.NewLine}{wrongStatusCodes.Select(error => error.Error).Flatten(Environment.NewLine)}{Environment.NewLine}");
        }
    }
